vec3 oot3d_directional_shadow_visibility() {
    uint flags = oot3d_directional_shadow.extent.w;
    if ((flags & 1u) == 0u ||
        oot3d_directional_shadow.extent.x == 0u ||
        oot3d_directional_shadow.extent.y == 0u) {
        return vec3(1.0);
