layout(set=0,binding=10) uniform sampler2D oot3d_directional_shadow_map;
layout(set=0,binding=12,std140) uniform Oot3dDirectionalShadowReceiver {
    mat4 view_to_shadow_texture;
    vec4 shadow_state;
    vec4 shadowed_direct_fraction;
    uvec4 extent;
} oot3d_directional_shadow;
float oot3d_directional_shadow_texel(
    ivec2 location, ivec2 map_extent, float receiver_depth) {
    float blocker = texelFetch(
        oot3d_directional_shadow_map,
        clamp(location, ivec2(0), map_extent - ivec2(1)), 0).r;
    return receiver_depth > blocker ? 1.0 : 0.0;
}
float oot3d_directional_shadow_axis_weight(
    int offset, int radius, float fraction) {
    if (offset == -radius) {
        return 1.0 - fraction;
    }
    if (offset == radius + 1) {
        return fraction;
    }
    return 1.0;
}
vec3 oot3d_directional_shadow_visibility() {
    uint flags = oot3d_directional_shadow.extent.w;
    if ((flags & 1u) == 0u ||
        oot3d_directional_shadow.extent.x == 0u ||
        oot3d_directional_shadow.extent.y == 0u) {
        return vec3(1.0);
    }
    vec4 shadow_h =
        oot3d_directional_shadow.view_to_shadow_texture *
        vec4(-pica_view, 1.0);
    if (abs(shadow_h.w) <= 1.0e-7) {
        return vec3(1.0);
    }
    vec3 shadow = shadow_h.xyz / shadow_h.w;
    if (any(lessThan(shadow, vec3(0.0))) ||
        any(greaterThan(shadow, vec3(1.0)))) {
        return vec3(1.0);
    }
    ivec2 map_extent = textureSize(oot3d_directional_shadow_map, 0);
    vec2 texel_position =
        shadow.xy * vec2(map_extent) - vec2(0.5);
    ivec2 texel_base = ivec2(floor(texel_position));
    vec2 texel_fraction = fract(texel_position);
    int radius = int(min(oot3d_directional_shadow.extent.z, 2u));
    float weighted_occlusion = 0.0;
    float weight_sum = 0.0;
    float receiver_depth = shadow.z -
        max(oot3d_directional_shadow.shadow_state.w, 0.0);
    // Combine the bilinear footprints of the (2r+1)^2 box taps. Shared
    // texels collapse to one weighted comparison, so radius 1 needs 16
    // fetches instead of 36 while coverage remains continuous in UV.
    for (int y = -2; y <= 3; ++y) {
        if (y < -radius || y > radius + 1) {
            continue;
        }
        float weight_y = oot3d_directional_shadow_axis_weight(
            y, radius, texel_fraction.y);
        for (int x = -2; x <= 3; ++x) {
            if (x < -radius || x > radius + 1) {
                continue;
            }
            float weight_x = oot3d_directional_shadow_axis_weight(
                x, radius, texel_fraction.x);
            float weight = weight_x * weight_y;
            weighted_occlusion += weight *
                oot3d_directional_shadow_texel(
                    texel_base + ivec2(x, y), map_extent,
                    receiver_depth);
            weight_sum += weight;
        }
    }
    float coverage = weight_sum > 0.0
        ? weighted_occlusion / weight_sum : 0.0;
    float strength = clamp(
        oot3d_directional_shadow.shadow_state.x, 0.0, 1.0);
    vec3 direct_fraction = clamp(
        oot3d_directional_shadow.shadowed_direct_fraction.rgb,
        vec3(0.0), vec3(1.0));
    return vec3(1.0) - coverage * strength * direct_fraction;
}
void main() {
    vec4 rounded_primary_color = vec4(byteround3(pica_primary_color.rgb), byteround1(pica_primary_color.a));
    vec4 primary_fragment_color = vec4(0.0);
    vec4 secondary_fragment_color = vec4(0.0);
    vec4 combiner_buffer = vec4(0.0);
    vec4 next_combiner_buffer = fragment_uniforms.combiner_buffer_color;
    vec4 combiner_output = vec4(0.0);
    // OOT3D_PICA_LIGHTING_EXTENSION_POINT
    rounded_primary_color.rgb *= oot3d_directional_shadow_visibility(); // OOT3D shadow lighting

    vec3 color_output_0 = byteround3(clamp(fma(rounded_primary_color.rgb, pica_sample_texture0(vec2(pica_texcoord0.x, 1.0 - pica_texcoord0.y)).rgb, pica_sample_texture1(vec2(pica_texcoord1.x, 1.0 - pica_texcoord1.y)).rgb), vec3(0.0), vec3(1.0)));
    float alpha_output_0 = byteround1(clamp(rounded_primary_color.a * pica_sample_texture0(vec2(pica_texcoord0.x, 1.0 - pica_texcoord0.y)).a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_0 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_0 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_1 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_1 = byteround1(clamp(combiner_output.a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_1 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_1 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_2 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_2 = byteround1(clamp(combiner_output.a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_2 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_2 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_3 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_3 = byteround1(clamp(combiner_output.a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_3 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_3 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_4 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_4 = byteround1(clamp(combiner_output.a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_4 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_4 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_5 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_5 = byteround1(clamp(combiner_output.a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_5 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_5 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    float pica_z_over_w = -gl_FragCoord.z;
    float pica_depth = pica_z_over_w * fragment_uniforms.depth_scale + fragment_uniforms.depth_offset;
    if (fragment_uniforms.w_buffering != 0) pica_depth /= gl_FragCoord.w;
    gl_FragDepth = pica_depth;
    pica_color = vec4(byteround3(combiner_output.rgb), byteround1(combiner_output.a));
}

